    args: [{ selector: "app-devoluciones", standalone: true, imports: [CommonModule, FormsModule], template: `<div class="header-actions">\r
  <div>\r
    <h3>Gesti\xF3n de Devoluciones y Cambios de Prendas</h3>\r
    <p class="subtitle">Administra devoluciones, notas digitales para delivery (en marcha vs completadas) y cambios dentro de la ventana de 30 d\xEDas.</p>\r
  </div>\r
  <div style="display: flex; gap: 10px; flex-wrap: wrap;">\r
    <button class="btn-primary" style="width: auto; background: linear-gradient(135deg, #4f46e5, #7c3aed);" (click)="showCrearNotaModal = true">\r
      + Emitir Nota de Devoluci\xF3n\r
    </button>\r
    <button class="btn-secondary" style="width: auto;" (click)="showCambioModal = true">Solicitar Cambio de Prenda</button>\r
    <button class="btn-secondary" style="width: auto;" (click)="showModal = true">+ Reembolso Directo</button>\r
  </div>\r
</div>\r
\r
<!-- Selector de Pesta\xF1as -->\r
<div class="tabs-nav" style="display: flex; gap: 12px; margin-bottom: 20px; border-bottom: 1px solid #e2e8f0; padding-bottom: 8px; flex-wrap: wrap;">\r
  <button \r
    (click)="tabActivo = 'notas'" \r
    [style.border-bottom]="tabActivo === 'notas' ? '3px solid var(--primary, #4f46e5)' : 'none'"\r
    [style.color]="tabActivo === 'notas' ? 'var(--primary, #4f46e5)' : '#64748b'"\r
    style="background: transparent; border: none; font-weight: 700; font-size: 1rem; padding: 8px 16px; cursor: pointer; display: flex; align-items: center; gap: 8px;">\r
    <span>Notas de Devoluci\xF3n (Delivery & Admin)</span>\r
    <span class="badge" style="background: #e0e7ff; color: #4338ca; font-weight: bold;">{{ notas.length }}</span>\r
  </button>\r
  <button \r
    (click)="tabActivo = 'cambios'" \r
    [style.border-bottom]="tabActivo === 'cambios' ? '3px solid var(--primary, #4f46e5)' : 'none'"\r
    [style.color]="tabActivo === 'cambios' ? 'var(--primary, #4f46e5)' : '#64748b'"\r
    style="background: transparent; border: none; font-weight: 600; font-size: 1rem; padding: 8px 16px; cursor: pointer; display: flex; align-items: center; gap: 6px;">\r
    <span>Cambios de Prendas (30 D\xEDas)</span>\r
    <span class="badge" style="background: #fef3c7; color: #b45309;">{{ cambios.length }}</span>\r
  </button>\r
  <button \r
    (click)="tabActivo = 'devoluciones'" \r
    [style.border-bottom]="tabActivo === 'devoluciones' ? '3px solid var(--primary, #4f46e5)' : 'none'"\r
    [style.color]="tabActivo === 'devoluciones' ? 'var(--primary, #4f46e5)' : '#64748b'"\r
    style="background: transparent; border: none; font-weight: 600; font-size: 1rem; padding: 8px 16px; cursor: pointer; display: flex; align-items: center; gap: 6px;">\r
    <span>Solicitudes B\xE1sicas</span>\r
    <span class="badge" style="background: #f1f5f9; color: #475569;">{{ devoluciones.length }}</span>\r
  </button>\r
</div>\r
\r
\r
<!-- TAB 1: DEVOLUCIONES -->\r
<div class="table-container" *ngIf="!isLoading && tabActivo === 'devoluciones'">\r
  <table>\r
    <thead>\r
      <tr>\r
        <th>ID</th>\r
        <th>ID Venta</th>\r
        <th>Tipo</th>\r
        <th>Motivo</th>\r
        <th>Estado</th>\r
        <th>Asignar Delivery</th>\r
      </tr>\r
    </thead>\r
    <tbody>\r
      <tr *ngFor="let dev of devoluciones">\r
        <td>#{{ dev.id }}</td>\r
        <td class="font-bold">#{{ dev.venta_id }}</td>\r
        <td><span class="badge" style="background-color: #f1f5f9; color: var(--text-main);">{{ dev.tipo_solicitud || 'Devoluci\xF3n' }}</span></td>\r
        <td>{{ dev.motivo }}</td>\r
        <td>\r
          <span class="badge" [ngClass]="{'badge-active': dev.estado === 'Completada', 'badge-inactive': dev.estado === 'Pendiente' || dev.estado === 'En Proceso'}">\r
            {{ dev.estado }}\r
          </span>\r
        </td>\r
        <td>\r
          <div *ngIf="dev.requiere_delivery === 1">\r
            <select class="input-field" (change)="asignarRepartidor(dev.id, $event)" *ngIf="dev.estado === 'Pendiente'" style="padding: 6px; width: auto;">\r
              <option value="">Asignar Repartidor...</option>\r
              <option *ngFor="let r of repartidores" [value]="r.id">{{ r.nombre_completo }}</option>\r
            </select>\r
            <span *ngIf="dev.estado !== 'Pendiente'" style="color: var(--text-muted); font-size: 0.9rem;">Ya asignado</span>\r
          </div>\r
          <div *ngIf="dev.requiere_delivery === 0">\r
            <span style="color: var(--text-muted); font-size: 0.9rem;">Cliente en tienda</span>\r
          </div>\r
        </td>\r
      </tr>\r
      <tr *ngIf="devoluciones.length === 0">\r
        <td colspan="6" class="empty-state">No hay devoluciones registradas</td>\r
      </tr>\r
    </tbody>\r
  </table>\r
</div>\r
\r
<!-- TAB 2: CAMBIOS DE PRENDAS (Req 7.2) -->\r
<div class="table-container" *ngIf="!isLoading && tabActivo === 'cambios'">\r
  <table>\r
    <thead>\r
      <tr>\r
        <th>ID Cambio</th>\r
        <th>Venta Origen</th>\r
        <th>Prenda Anterior</th>\r
        <th>Prenda Nueva</th>\r
        <th>Diferencia Precio</th>\r
        <th>Motivo</th>\r
        <th>Fecha Registro</th>\r
        <th>Estado</th>\r
      </tr>\r
    </thead>\r
    <tbody>\r
      <tr *ngFor="let c of cambios">\r
        <td><strong>#{{ c.id }}</strong></td>\r
        <td><span class="badge" style="background: #ede9fe; color: #6d28d9;">Venta #{{ c.venta_id }}</span></td>\r
        <td>\r
          <div><strong>{{ getProductoNombre(c.producto_anterior_id) }}</strong></div>\r
          <small class="text-muted">Talla: {{ getTallaNombre(c.talla_anterior_id) }} | Color: {{ getColorNombre(c.color_anterior_id) }}</small>\r
        </td>\r
        <td>\r
          <div><strong style="color: #059669;">{{ getProductoNombre(c.producto_nuevo_id) }}</strong></div>\r
          <small class="text-muted">Talla: {{ getTallaNombre(c.talla_nueva_id) }} | Color: {{ getColorNombre(c.color_nueva_id) }}</small>\r
        </td>\r
        <td>\r
          <span [style.color]="c.diferencia_precio > 0 ? '#b91c1c' : (c.diferencia_precio < 0 ? '#059669' : '#475569')">\r
            {{ c.diferencia_precio >= 0 ? '+' : '' }}Bs. {{ c.diferencia_precio }}\r
          </span>\r
        </td>\r
        <td style="max-width: 200px; font-size: 0.88rem;">{{ c.motivo }}</td>\r
        <td style="font-size: 0.85rem; color: #64748b;">{{ c.fecha_cambio | date:'dd/MM/yyyy HH:mm' }}</td>\r
        <td>\r
          <span class="badge" style="background: #dcfce7; color: #15803d; font-weight: 600;">{{ c.estado || 'Procesado' }}</span>\r
        </td>\r
      </tr>\r
      <tr *ngIf="cambios.length === 0">\r
        <td colspan="8" class="empty-state">\r
          <div style="padding: 24px;">\r
            <p>No se han registrado solicitudes de cambio de prendas en este tenant.</p>\r
            <button class="btn-primary" style="margin-top: 12px; width: auto;" (click)="showCambioModal = true">Registrar Primer Cambio</button>\r
          </div>\r
        </td>\r
      </tr>\r
    </tbody>\r
  </table>\r
</div>\r
\r
<!-- TAB 3: NOTAS DE DEVOLUCI\xD3N PARA DELIVERY Y ADMIN -->\r
<div *ngIf="!isLoading && tabActivo === 'notas'">\r
  <!-- Sub-Filtros de Notas -->\r
  <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; background: #f8fafc; padding: 12px 16px; border-radius: 8px; border: 1px solid #e2e8f0;">\r
    <div style="display: flex; gap: 8px;">\r
      <button \r
        (click)="filtroNotas = 'EN_MARCHA'" \r
        [style.background]="filtroNotas === 'EN_MARCHA' ? '#4f46e5' : '#ffffff'"\r
        [style.color]="filtroNotas === 'EN_MARCHA' ? '#ffffff' : '#475569'"\r
        style="border: 1px solid #cbd5e1; border-radius: 6px; padding: 6px 14px; font-weight: 600; font-size: 0.88rem; cursor: pointer;">\r
        En Marcha / Pendientes\r
      </button>\r
      <button \r
        (click)="filtroNotas = 'COMPLETADA'" \r
        [style.background]="filtroNotas === 'COMPLETADA' ? '#10b981' : '#ffffff'"\r
        [style.color]="filtroNotas === 'COMPLETADA' ? '#ffffff' : '#475569'"\r
        style="border: 1px solid #cbd5e1; border-radius: 6px; padding: 6px 14px; font-weight: 600; font-size: 0.88rem; cursor: pointer;">\r
        Completadas (Hist\xF3rico Admin)\r
      </button>\r
      <button \r
        (click)="filtroNotas = 'TODAS'" \r
        [style.background]="filtroNotas === 'TODAS' ? '#64748b' : '#ffffff'"\r
        [style.color]="filtroNotas === 'TODAS' ? '#ffffff' : '#475569'"\r
        style="border: 1px solid #cbd5e1; border-radius: 6px; padding: 6px 14px; font-weight: 600; font-size: 0.88rem; cursor: pointer;">\r
        Todas las Notas\r
      </button>\r
    </div>\r
    <span style="font-size: 0.85rem; color: #64748b;">\r
      Total mostradas: <strong>{{ notasFiltradas.length }}</strong> notas de devoluci\xF3n\r
    </span>\r
  </div>\r
\r
  <div class="table-container">\r
    <table>\r
      <thead>\r
        <tr>\r
          <th>C\xF3digo Nota</th>\r
          <th>Venta Ref.</th>\r
          <th>Tipo Solicitud</th>\r
          <th>Prenda Devuelta</th>\r
          <th>Prenda Sustituta</th>\r
          <th>Ajuste de Precio</th>\r
          <th>Estado</th>\r
          <th>Acciones</th>\r
        </tr>\r
      </thead>\r
      <tbody>\r
        <tr *ngFor="let n of notasFiltradas">\r
          <td>\r
            <strong style="color: #4f46e5; font-family: monospace; font-size: 0.95rem;">{{ n.codigo_nota }}</strong>\r
            <div style="font-size: 0.75rem; color: #94a3b8;">{{ n.fecha_creacion | date:'dd/MM/yyyy HH:mm' }}</div>\r
          </td>\r
          <td><span class="badge" style="background: #f1f5f9; color: #334155;">#{{ n.venta_id }}</span></td>\r
          <td>\r
            <span class="badge" [style.background]="n.tipo_solicitud.includes('Mayor') ? '#fef2f2' : '#f0fdf4'" [style.color]="n.tipo_solicitud.includes('Mayor') ? '#b91c1c' : '#15803d'">\r
              {{ n.tipo_solicitud }}\r
            </span>\r
          </td>\r
          <td style="font-size: 0.88rem;">{{ n.prenda_devuelta_info }}</td>\r
          <td style="font-size: 0.88rem;">{{ n.prenda_nueva_info || 'Devoluci\xF3n' }}</td>\r
          <td>\r
            <div *ngIf="n.diferencia_precio > 0" style="color: #dc2626; font-weight: 600; font-size: 0.88rem;">\r
              +{{ n.diferencia_precio }} Bs. (Paga Cliente)\r
            </div>\r
            <div *ngIf="n.diferencia_precio < 0" style="color: #059669; font-weight: 600; font-size: 0.88rem;">\r
              {{ n.diferencia_precio }} Bs. (Cup\xF3n Cr\xE9dito)\r
            </div>\r
            <div *ngIf="n.diferencia_precio === 0" style="color: #64748b; font-size: 0.88rem;">\r
              Sin diferencia (0.00 Bs.)\r
            </div>\r
            <small *ngIf="n.cupon_generado" style="display: block; font-family: monospace; color: #4338ca;">\r
              {{ n.cupon_generado }}\r
            </small>\r
          </td>\r
          <td>\r
            <span class="badge" [style.background]="n.estado === 'EN_MARCHA' ? '#fef3c7' : '#dcfce7'" [style.color]="n.estado === 'EN_MARCHA' ? '#b45309' : '#15803d'">\r
              {{ n.estado === 'EN_MARCHA' ? 'En Marcha' : 'Completada' }}\r
            </span>\r
            <div *ngIf="n.visible_para_cliente" style="font-size: 0.72rem; color: #6366f1; margin-top: 3px;">\r
              Visible en app cliente\r
            </div>\r
            <div *ngIf="!n.visible_para_cliente && n.estado === 'COMPLETADA'" style="font-size: 0.72rem; color: #94a3b8; margin-top: 3px;">\r
              Archivada en Admin\r
            </div>\r
          </td>\r
          <td>\r
            <div style="display: flex; gap: 6px;">\r
              <button \r
                class="btn-secondary" \r
                style="padding: 5px 10px; font-size: 0.82rem; width: auto;" \r
                (click)="abrirNotaDelivery(n)">\r
                Nota Delivery\r
              </button>\r
              <button \r
                *ngIf="n.estado === 'EN_MARCHA'" \r
                class="btn-primary" \r
                style="padding: 5px 10px; font-size: 0.82rem; width: auto; background: #10b981;" \r
                (click)="completarNota(n.id)">\r
                Completar\r
              </button>\r
            </div>\r
          </td>\r
        </tr>\r
        <tr *ngIf="notasFiltradas.length === 0">\r
          <td colspan="8" class="empty-state">\r
            <div style="padding: 24px;">\r
              <p>No hay notas de devoluci\xF3n registradas en esta categor\xEDa.</p>\r
              <button class="btn-primary" style="margin-top: 10px; width: auto;" (click)="showCrearNotaModal = true">+ Emitir Primera Nota de Devoluci\xF3n</button>\r
            </div>\r
          </td>\r
        </tr>\r
      </tbody>\r
    </table>\r
  </div>\r
</div>\r
\r
<!-- MODAL: SOLICITAR DEVOLUCION -->\r
\r
<div class="modal-overlay" *ngIf="showModal" (click)="showModal = false">\r
  <div class="modal-content glass-card" (click)="$event.stopPropagation()">\r
    <div class="modal-header">\r
      <h3>Solicitar Nueva Devoluci\xF3n</h3>\r
      <button class="btn-close" (click)="showModal = false">\xD7</button>\r
    </div>\r
    <div class="modal-body">\r
      <div class="input-group">\r
        <label>Seleccionar Venta</label>\r
        <select class="input-field" [(ngModel)]="nuevaDev.venta_id">\r
          <option value="">Seleccione una venta...</option>\r
          <option *ngFor="let v of ventas" [value]="v.id">Venta #{{ v.id }} - Total: Bs. {{ v.total }}</option>\r
        </select>\r
      </div>\r
      <div class="input-group">\r
        <label>Tipo de Solicitud</label>\r
        <select class="input-field" [(ngModel)]="nuevaDev.tipo_solicitud">\r
          <option value="Devoluci\xF3n">Reembolso / Devoluci\xF3n</option>\r
          <option value="Cambio">Cambio de Talla / Color</option>\r
        </select>\r
      </div>\r
\r
      <div class="input-group">\r
        <label>M\xE9todo de Entrega</label>\r
        <label style="display: flex; align-items: center; gap: 8px; font-weight: normal; margin-top: 5px;">\r
          <input type="checkbox" [(ngModel)]="nuevaDev.requiere_delivery">\r
          Solicitar recojo y env\xEDo por Delivery (Costo Extra)\r
        </label>\r
      </div>\r
\r
      <div class="input-group">\r
        <label>Detalle o Motivo</label>\r
        <textarea class="input-field" rows="3" [(ngModel)]="nuevaDev.motivo" placeholder="Ej: Devoluci\xF3n por inconformidad"></textarea>\r
      </div>\r
    </div>\r
    <div class="modal-footer">\r
      <button class="btn-secondary" (click)="showModal = false">Cancelar</button>\r
      <button class="btn-primary" style="width: auto;" (click)="crearDevolucion()">Guardar Devoluci\xF3n</button>\r
    </div>\r
  </div>\r
</div>\r
\r
<!-- MODAL: REGISTRAR CAMBIO DE PRENDA (Req 7.2 - Ventana de 30 d\xEDas) -->\r
<div class="modal-overlay" *ngIf="showCambioModal" (click)="showCambioModal = false">\r
  <div class="modal-content glass-card" style="max-width: 720px;" (click)="$event.stopPropagation()">\r
    <div class="modal-header">\r
      <h3>Cambio de Prenda de Vestir (Ventana 30 D\xEDas)</h3>\r
      <button class="btn-close" (click)="showCambioModal = false">\xD7</button>\r
    </div>\r
    <div class="modal-body">\r
      \r
      <!-- Banner Regla de Negocio -->\r
      <div style="background: #eff6ff; border: 1px solid #bfdbfe; border-radius: 8px; padding: 12px; margin-bottom: 16px; font-size: 0.88rem; color: #1e40af;">\r
        <strong>\u2139\uFE0F Regla de Negocio (Req 7.2):</strong>\r
        El cambio de prendas solo es v\xE1lido dentro de los <strong>30 d\xEDas naturales</strong> contados a partir de la emisi\xF3n del comprobante.\r
        El sistema reintegrar\xE1 autom\xE1ticamente la prenda entregada al inventario y descontar\xE1 la nueva prenda seleccionada.\r
      </div>\r
\r
      <!-- Alertas -->\r
      <div *ngIf="cambioError" style="background: #fef2f2; border: 1px solid #fecaca; color: #b91c1c; padding: 10px 14px; border-radius: 8px; margin-bottom: 14px; font-size: 0.9rem;">\r
        {{ cambioError }}\r
      </div>\r
      <div *ngIf="cambioSuccess" style="background: #f0fdf4; border: 1px solid #bbf7d0; color: #15803d; padding: 10px 14px; border-radius: 8px; margin-bottom: 14px; font-size: 0.9rem;">\r
        {{ cambioSuccess }}\r
      </div>\r
\r
      <div class="input-group">\r
        <label>Venta Asociada (Comprobante)</label>\r
        <select class="input-field" [(ngModel)]="nuevoCambio.venta_id">\r
          <option value="">Seleccione una venta...</option>\r
          <option *ngFor="let v of ventas" [value]="v.id">Venta #{{ v.id }} - Bs. {{ v.total }} (Fecha: {{ v.fecha | date:'dd/MM/yyyy' }})</option>\r
        </select>\r
      </div>\r
\r
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px;">\r
        \r
        <!-- Prenda Anterior -->\r
        <div style="background: #f8fafc; border: 1px solid #e2e8f0; padding: 12px; border-radius: 8px;">\r
          <h4 style="margin: 0 0 10px 0; color: #dc2626; font-size: 0.95rem;">Prenda a Devolver (Reintegro Stock)</h4>\r
          \r
          <div class="input-group">\r
            <label style="font-size: 0.82rem;">Producto</label>\r
            <select class="input-field" [(ngModel)]="nuevoCambio.producto_anterior_id">\r
              <option value="">Seleccione prenda...</option>\r
              <option *ngFor="let p of productos" [value]="p.id">{{ p.nombre }} (Bs. {{ p.precio }})</option>\r
            </select>\r
          </div>\r
\r
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px;">\r
            <div class="input-group">\r
              <label style="font-size: 0.82rem;">Talla</label>\r
              <select class="input-field" [(ngModel)]="nuevoCambio.talla_anterior_id">\r
                <option *ngFor="let t of tallas" [value]="t.id">{{ t.nombre }}</option>\r
              </select>\r
            </div>\r
            <div class="input-group">\r
              <label style="font-size: 0.82rem;">Color</label>\r
              <select class="input-field" [(ngModel)]="nuevoCambio.color_anterior_id">\r
                <option *ngFor="let c of colores" [value]="c.id">{{ c.nombre }}</option>\r
              </select>\r
            </div>\r
          </div>\r
        </div>\r
\r
        <!-- Prenda Nueva -->\r
        <div style="background: #f0fdf4; border: 1px solid #bbf7d0; padding: 12px; border-radius: 8px;">\r
          <h4 style="margin: 0 0 10px 0; color: #16a34a; font-size: 0.95rem;">Nueva Prenda a Entregar (Deducci\xF3n Stock)</h4>\r
          \r
          <div class="input-group">\r
            <label style="font-size: 0.82rem;">Producto</label>\r
            <select class="input-field" [(ngModel)]="nuevoCambio.producto_nuevo_id">\r
              <option value="">Seleccione prenda...</option>\r
              <option *ngFor="let p of productos" [value]="p.id">{{ p.nombre }} (Bs. {{ p.precio }})</option>\r
            </select>\r
          </div>\r
\r
          <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px;">\r
            <div class="input-group">\r
              <label style="font-size: 0.82rem;">Talla</label>\r
              <select class="input-field" [(ngModel)]="nuevoCambio.talla_nueva_id">\r
                <option *ngFor="let t of tallas" [value]="t.id">{{ t.nombre }}</option>\r
              </select>\r
            </div>\r
            <div class="input-group">\r
              <label style="font-size: 0.82rem;">Color</label>\r
              <select class="input-field" [(ngModel)]="nuevoCambio.color_nueva_id">\r
                <option *ngFor="let c of colores" [value]="c.id">{{ c.nombre }}</option>\r
              </select>\r
            </div>\r
          </div>\r
        </div>\r
\r
      </div>\r
\r
      <div style="display: grid; grid-template-columns: 2fr 1fr; gap: 12px; margin-top: 14px;">\r
        <div class="input-group">\r
          <label>Motivo del Cambio</label>\r
          <input type="text" class="input-field" [(ngModel)]="nuevoCambio.motivo" placeholder="Ej: Cambio de talla incorrecta / color no deseado">\r
        </div>\r
        <div class="input-group">\r
          <label>Diferencia de Precio (Bs.)</label>\r
          <input type="number" step="0.5" class="input-field" [(ngModel)]="nuevoCambio.diferencia_precio" placeholder="0.0">\r
        </div>\r
      </div>\r
\r
    </div>\r
    <div class="modal-footer">\r
      <button class="btn-secondary" (click)="showCambioModal = false">Cancelar</button>\r
      <button class="btn-primary" style="width: auto;" (click)="registrarCambio()">Procesar Cambio</button>\r
    </div>\r
  </div>\r
</div>\r
\r
<!-- MODAL: CREAR NOTA DE DEVOLUCI\xD3N DIGITAL -->\r
<div class="modal-overlay" *ngIf="showCrearNotaModal" (click)="showCrearNotaModal = false">\r
  <div class="modal-content glass-card" style="max-width: 680px;" (click)="$event.stopPropagation()">\r
    <div class="modal-header">\r
      <h3>Emitir Nota de Devoluci\xF3n Oficial</h3>\r
      <button class="btn-close" (click)="showCrearNotaModal = false">\xD7</button>\r
    </div>\r
    <div class="modal-body">\r
      <p style="font-size: 0.88rem; color: #64748b; margin-bottom: 14px;">\r
        Esta nota generar\xE1 un comprobante digital para que el cliente lo muestre al repartidor de delivery. Si existe variaci\xF3n de precios, se notificar\xE1 el cobro de diferencia o la emisi\xF3n de cup\xF3n.\r
      </p>\r
\r
      <div *ngIf="notaError" style="background: #fef2f2; border: 1px solid #fecaca; color: #b91c1c; padding: 10px; border-radius: 6px; margin-bottom: 12px; font-size: 0.88rem;">\r
        {{ notaError }}\r
      </div>\r
      <div *ngIf="notaSuccess" style="background: #f0fdf4; border: 1px solid #bbf7d0; color: #15803d; padding: 10px; border-radius: 6px; margin-bottom: 12px; font-size: 0.88rem;">\r
        {{ notaSuccess }}\r
      </div>\r
\r
      <div class="input-group">\r
        <label>Venta Original Asociada</label>\r
        <select class="input-field" [(ngModel)]="nuevaNota.venta_id">\r
          <option value="">Seleccione una venta...</option>\r
          <option *ngFor="let v of ventas" [value]="v.id">Venta #{{ v.id }} - Bs. {{ v.total }}</option>\r
        </select>\r
      </div>\r
\r
      <div class="input-group">\r
        <label>Tipo de Solicitud</label>\r
        <select class="input-field" [(ngModel)]="nuevaNota.tipo_solicitud">\r
          <option value="Cambio por Mayor Valor">Cambio por Prenda de Mayor Valor (Cliente paga diferencia)</option>\r
          <option value="Cambio por Menor Valor">Cambio por Prenda de Menor Valor (Cup\xF3n cr\xE9dito / Reembolso tienda)</option>\r
          <option value="Cambio de Talla o Color">Cambio Directo de Talla o Color (Mismo precio)</option>\r
          <option value="Devoluci\xF3n Directa">Devoluci\xF3n y Retiro de Producto</option>\r
        </select>\r
      </div>\r
\r
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 14px;">\r
        <div class="input-group">\r
          <label>Prenda a Recoger (Devuelta)</label>\r
          <input type="text" class="input-field" [(ngModel)]="nuevaNota.prenda_devuelta_info" placeholder="Ej: Camisa Slim Fit Azul Talla M">\r
        </div>\r
        <div class="input-group">\r
          <label>Precio Pagado Original (Bs.)</label>\r
          <input type="number" class="input-field" [(ngModel)]="nuevaNota.precio_prenda_original">\r
        </div>\r
      </div>\r
\r
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 14px;" *ngIf="nuevaNota.tipo_solicitud !== 'Devoluci\xF3n Directa'">\r
        <div class="input-group">\r
          <label>Prenda Sustituta (A Entregar)</label>\r
          <input type="text" class="input-field" [(ngModel)]="nuevaNota.prenda_nueva_info" placeholder="Ej: Chaqueta Cuero Sint\xE9tico Talla L">\r
        </div>\r
        <div class="input-group">\r
          <label>Precio Prenda Nueva (Bs.)</label>\r
          <input type="number" class="input-field" [(ngModel)]="nuevaNota.precio_prenda_nueva">\r
        </div>\r
      </div>\r
\r
      <!-- C\xE1lculo Autom\xE1tico Preview -->\r
      <div style="background: #f8fafc; border: 1px dashed #cbd5e1; border-radius: 8px; padding: 12px; margin-top: 10px;">\r
        <div style="display: flex; justify-content: space-between; font-size: 0.9rem;">\r
          <span>Diferencia Estimada:</span>\r
          <strong>Bs. {{ (nuevaNota.precio_prenda_nueva - nuevaNota.precio_prenda_original).toFixed(2) }}</strong>\r
        </div>\r
        <small style="color: #64748b; display: block; margin-top: 4px;">\r
          * Si el resultado es positivo (+), el cliente abona la diferencia al delivery. Si es negativo (-), se genera autom\xE1ticamente cup\xF3n comercial.\r
        </small>\r
      </div>\r
\r
      <div class="input-group" style="margin-top: 12px;">\r
        <label>Motivo y Observaciones para el Delivery</label>\r
        <textarea class="input-field" rows="2" [(ngModel)]="nuevaNota.motivo" placeholder="Ej: Cliente solicita cambio por prenda m\xE1s abrigada."></textarea>\r
      </div>\r
\r
    </div>\r
    <div class="modal-footer">\r
      <button class="btn-secondary" (click)="showCrearNotaModal = false">Cancelar</button>\r
      <button class="btn-primary" style="width: auto; background: #4f46e5;" (click)="crearNotaDevolucion()">Generar Nota Digital</button>\r
    </div>\r
  </div>\r
</div>\r
\r
<!-- MODAL: FORMATO NOTA DE DEVOLUCI\xD3N PARA DELIVERY (Comprobante Visual) -->\r
<div class="modal-overlay" *ngIf="showNotaDeliveryModal && notaSeleccionada" (click)="showNotaDeliveryModal = false">\r
  <div class="modal-content glass-card" style="max-width: 540px; padding: 0; overflow: hidden; border: 2px solid #6366f1;" (click)="$event.stopPropagation()">\r
    \r
    <!-- Encabezado Estilo Voucher Delivery -->\r
    <div style="background: linear-gradient(135deg, #312e81, #4338ca); color: white; padding: 20px; text-align: center;">\r
      <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">\r
        <span style="font-size: 0.8rem; background: rgba(255,255,255,0.2); padding: 3px 8px; border-radius: 4px;">FASHIONSTORE LOGISTICS</span>\r
        <button (click)="showNotaDeliveryModal = false" style="background: transparent; border: none; color: white; font-size: 1.2rem; cursor: pointer;">\xD7</button>\r
      </div>\r
      <h3 style="margin: 0; font-size: 1.3rem; letter-spacing: 0.5px;">NOTA OFICIAL DE DEVOLUCI\xD3N</h3>\r
      <div style="font-family: monospace; font-size: 1.4rem; font-weight: bold; color: #a5b4fc; margin-top: 6px;">\r
        {{ notaSeleccionada.codigo_nota }}\r
      </div>\r
      <div style="font-size: 0.82rem; color: #e0e7ff; margin-top: 4px;">\r
        Presentar este comprobante digital al personal de delivery\r
      </div>\r
    </div>\r
\r
    <!-- Cuerpo del Comprobante -->\r
    <div style="padding: 24px; background: #ffffff;">\r
      \r
      <!-- Estado y Notificaci\xF3n de Pago -->\r
      <div [style.background]="notaSeleccionada.diferencia_precio > 0 ? '#fef2f2' : '#f0fdf4'" \r
           [style.border]="notaSeleccionada.diferencia_precio > 0 ? '1px solid #fecaca' : '1px solid #bbf7d0'" \r
           style="border-radius: 8px; padding: 14px; margin-bottom: 18px; text-align: center;">\r
        <div style="font-size: 0.85rem; color: #475569; text-transform: uppercase; font-weight: bold;">\r
          Instrucci\xF3n Financiera para Delivery\r
        </div>\r
        <div *ngIf="notaSeleccionada.diferencia_precio > 0" style="color: #b91c1c; font-size: 1.25rem; font-weight: bold; margin-top: 4px;">\r
          COBRAR AL CLIENTE: Bs. {{ notaSeleccionada.diferencia_precio.toFixed(2) }}\r
        </div>\r
        <div *ngIf="notaSeleccionada.diferencia_precio < 0" style="color: #15803d; font-size: 1.15rem; font-weight: bold; margin-top: 4px;">\r
          TIENDA OTORGA CUP\xD3N: {{ notaSeleccionada.cupon_generado || 'CUPON-DEV' }}\r
        </div>\r
        <div *ngIf="notaSeleccionada.diferencia_precio === 0" style="color: #475569; font-size: 1.15rem; font-weight: bold; margin-top: 4px;">\r
          CAMBIO EXACTO SIN COSTO ADICIONAL\r
        </div>\r
        <div style="font-size: 0.8rem; color: #64748b; margin-top: 6px;">\r
          {{ notaSeleccionada.mensaje_notificacion }}\r
        </div>\r
      </div>\r
\r
      <!-- Datos de la Operaci\xF3n -->\r
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 16px; font-size: 0.85rem; border-bottom: 1px dashed #cbd5e1; padding-bottom: 14px;">\r
        <div>\r
          <span style="color: #64748b; display: block;">Venta de Referencia:</span>\r
          <strong>#{{ notaSeleccionada.venta_id }}</strong>\r
        </div>\r
        <div>\r
          <span style="color: #64748b; display: block;">Fecha de Emisi\xF3n:</span>\r
          <strong>{{ notaSeleccionada.fecha_creacion | date:'dd/MM/yyyy HH:mm' }}</strong>\r
        </div>\r
        <div>\r
          <span style="color: #64748b; display: block;">Tipo de Operaci\xF3n:</span>\r
          <strong>{{ notaSeleccionada.tipo_solicitud }}</strong>\r
        </div>\r
        <div>\r
          <span style="color: #64748b; display: block;">Estado Operativo:</span>\r
          <span class="badge" [style.background]="notaSeleccionada.estado === 'EN_MARCHA' ? '#fef3c7' : '#dcfce7'" [style.color]="notaSeleccionada.estado === 'EN_MARCHA' ? '#b45309' : '#15803d'">\r
            {{ notaSeleccionada.estado }}\r
          </span>\r
        </div>\r
      </div>\r
\r
      <!-- Detalle de Prendas -->\r
      <div style="background: #f8fafc; border-radius: 8px; padding: 14px; margin-bottom: 18px; font-size: 0.88rem;">\r
        <div style="margin-bottom: 10px;">\r
          <span style="color: #ef4444; font-weight: bold;">PRENDA A RECOGER (Cliente entrega):</span>\r
          <div style="font-weight: 600; margin-top: 2px;">{{ notaSeleccionada.prenda_devuelta_info }}</div>\r
          <small style="color: #64748b;">Valor original: Bs. {{ notaSeleccionada.precio_prenda_original }}</small>\r
        </div>\r
        <div *ngIf="notaSeleccionada.prenda_nueva_info">\r
          <span style="color: #10b981; font-weight: bold;">PRENDA A ENTREGAR (Delivery entrega):</span>\r
          <div style="font-weight: 600; margin-top: 2px;">{{ notaSeleccionada.prenda_nueva_info }}</div>\r
          <small style="color: #64748b;">Valor nueva prenda: Bs. {{ notaSeleccionada.precio_prenda_nueva }}</small>\r
        </div>\r
      </div>\r
\r
      <!-- Motivo -->\r
      <div style="font-size: 0.85rem; color: #475569; margin-bottom: 20px;">\r
        <strong>Motivo registrado:</strong> {{ notaSeleccionada.motivo }}\r
      </div>\r
\r
      <!-- C\xF3digo de Barras Simulado para Escaneo del Delivery -->\r
      <div style="text-align: center; border: 1px solid #e2e8f0; border-radius: 6px; padding: 12px; background: #fafafa;">\r
        <div style="font-family: monospace; letter-spacing: 5px; font-size: 1.1rem; font-weight: bold;">\r
          ||||| | |||| ||| ||||| || ||||\r
        </div>\r
        <span style="font-family: monospace; font-size: 0.8rem; color: #64748b;">*{{ notaSeleccionada.codigo_nota }}*</span>\r
      </div>\r
\r
    </div>\r
\r
    <!-- Footer Modal -->\r
    <div style="padding: 16px 24px; background: #f1f5f9; display: flex; justify-content: space-between; align-items: center;">\r
      <button class="btn-secondary" style="width: auto;" (click)="showNotaDeliveryModal = false">Cerrar</button>\r
      <button \r
        *ngIf="notaSeleccionada.estado === 'EN_MARCHA'" \r
        class="btn-primary" \r
        style="width: auto; background: #10b981;" \r
        (click)="completarNota(notaSeleccionada.id)">\r
        Confirmar y Completar Entrega\r
      </button>\r
    </div>\r
\r
  </div>\r
</div>\r
\r
`, styles: ["/* src/app/pages/dashboard/devoluciones/devoluciones.css */\n.header-actions {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 24px;\n}\nh3 {\n  color: var(--text-main);\n  font-size: 1.5rem;\n}\n.subtitle {\n  color: var(--text-muted);\n  font-size: 0.95rem;\n}\n.btn-primary {\n  width: auto;\n  padding: 10px 20px;\n}\n.badge-active {\n  background-color: #10b981;\n  color: white;\n  padding: 4px 8px;\n  border-radius: 12px;\n  font-size: 0.8rem;\n  font-weight: 600;\n}\n.badge-inactive {\n  background-color: #f59e0b;\n  color: white;\n  padding: 4px 8px;\n  border-radius: 12px;\n  font-size: 0.8rem;\n  font-weight: 600;\n}\n.table-container {\n  background: white;\n  border: 1px solid rgba(148, 163, 184, 0.3);\n  border-radius: 8px;\n  overflow: hidden;\n}\ntable {\n  width: 100%;\n  border-collapse: collapse;\n}\nth,\ntd {\n  padding: 16px;\n  text-align: left;\n  border-bottom: 1px solid #e2e8f0;\n}\nth {\n  background-color: #f8fafc;\n  color: var(--text-muted);\n  font-weight: 600;\n  font-size: 0.85rem;\n  text-transform: uppercase;\n}\ntd {\n  color: var(--text-main);\n  font-size: 0.95rem;\n}\n.font-bold {\n  font-weight: 600;\n}\n.text-orange {\n  color: var(--primary);\n}\n.text-muted {\n  color: var(--text-muted);\n  font-size: 0.9rem;\n}\n.empty-state {\n  padding: 40px;\n  text-align: center;\n  color: var(--text-muted);\n}\n.modal-overlay {\n  position: fixed;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  background: rgba(15, 23, 42, 0.4);\n  -webkit-backdrop-filter: blur(4px);\n  backdrop-filter: blur(4px);\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  z-index: 1000;\n}\n.modal-content {\n  width: 100%;\n  max-width: 650px;\n  background: white;\n  padding: 24px;\n  max-height: 85vh;\n  box-sizing: border-box;\n  border-radius: 16px;\n  display: flex;\n  flex-direction: column;\n}\n.modal-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 20px;\n  flex-shrink: 0;\n}\n.btn-close {\n  background: transparent;\n  border: none;\n  font-size: 1.5rem;\n  color: var(--text-muted);\n  cursor: pointer;\n}\n.modal-body {\n  margin-bottom: 24px;\n  overflow-y: auto;\n  flex-grow: 1;\n  padding-right: 10px;\n}\n.modal-footer {\n  display: flex;\n  justify-content: flex-end;\n  gap: 12px;\n  flex-shrink: 0;\n}\n.btn-secondary {\n  width: auto;\n  padding: 10px 20px;\n}\n.input-group {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  margin-bottom: 16px;\n}\n.input-group label {\n  font-size: 0.9rem;\n  font-weight: 600;\n  color: var(--text-main);\n}\nselect.input-field {\n  cursor: pointer;\n}\ntextarea.input-field {\n  resize: vertical;\n}\n/*# sourceMappingURL=devoluciones.css.map */\n"] }]
